/**
 * Next.js App Router Templates Generator for mern-integrations CLI
 */

export function generateNextPaymentRoute(options = {}) {
  const payments = Array.isArray(options.payments) ? options.payments : [];
  const primary = payments[0] || 'phonepe';

  return `/**
 * Next.js App Router Payment Endpoint
 * Route: /api/integrations/payments
 * Auto-generated by: npx mern-integrations init
 */

import { NextResponse } from 'next/server';
import { ${primary} } from '../../config.js';
import { ValidationError, IntegrationError } from 'mern-integrations';

export async function POST(request) {
  try {
    const body = await request.json();
    const { action = 'create-order', ...data } = body;

    if (action === 'create-order') {
      const order = await ${primary}.createOrder({
        amount: Number(data.amount),
        currency: data.currency || 'INR',
        receipt: \`rcpt_\${Date.now()}\`,
        customerId: data.customerId
      });
      return NextResponse.json(order, { status: 201 });
    }

    if (action === 'verify') {
      let result;
      if (typeof ${primary}.verifyPayment === 'function') {
        result = await ${primary}.verifyPayment(data);
      } else if (typeof ${primary}.verifyCallback === 'function') {
        result = await ${primary}.verifyCallback(data);
      }
      return NextResponse.json(result, { status: 200 });
    }

    return NextResponse.json({ error: 'Unknown action' }, { status: 400 });
  } catch (error) {
    if (error instanceof ValidationError) {
      return NextResponse.json({ error: error.message, details: error.details }, { status: 400 });
    }
    if (error instanceof IntegrationError) {
      return NextResponse.json(
        { error: error.message, code: error.code, provider: error.provider },
        { status: error.statusCode || 500 }
      );
    }
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
  }
}
`;
}

export function generateNextWebhookRoute(options = {}) {
  const payments = Array.isArray(options.payments) ? options.payments : [];
  const primary = payments[0] || 'phonepe';

  return `/**
 * Next.js App Router Webhook Endpoint
 * Route: /api/integrations/webhooks
 * Auto-generated by: npx mern-integrations init
 */

import { NextResponse } from 'next/server';
import { normalizeWebhookEvent } from 'mern-integrations';
import { ${primary} } from '../../config.js';

export async function POST(request) {
  try {
    const rawBody = await request.text();
    const headers = Object.fromEntries(request.headers.entries());

    // 1. Verify signature if provider supports it
    if (typeof ${primary}.verifyWebhook === 'function') {
      const sigHeader =
        headers['x-razorpay-signature'] ||
        headers['stripe-signature'] ||
        headers['x-verify'] ||
        headers['x-webhook-signature'] ||
        headers['x-signature'] ||
        '';

      const timestampHeader =
        headers['x-webhook-timestamp'] ||
        headers['x-timestamp'] ||
        headers['timestamp'] ||
        '';

      const verifyResult = await ${primary}.verifyWebhook({
        payload: rawBody,
        signature: sigHeader,
        timestamp: timestampHeader
      });

      if (!verifyResult || verifyResult.data?.verified === false) {
        return NextResponse.json({ error: 'Invalid webhook signature' }, { status: 400 });
      }
    }

    // 2. Parse and normalize event
    let payload;
    try {
      payload = JSON.parse(rawBody);
    } catch {
      payload = rawBody;
    }

    const event = normalizeWebhookEvent('${primary}', payload);

    console.log(\`[Next.js Webhook] \${event.provider} - \${event.eventType} (\${event.resource?.id})\`);

    // 3. Dispatch to your business logic / database
    // switch(event.eventType) { case 'payment.success': ... }

    return NextResponse.json({ received: true, id: event.id });
  } catch (error) {
    console.error('[Webhook Route Error]:', error);
    return NextResponse.json({ error: 'Webhook processing failed' }, { status: 500 });
  }
}
`;
}
